export type Tarefa = {
  id: number
  titulo: string
  concluida: boolean
}

const ESTADOS_VALIDOS: readonly string[] = ['todas', 'abertas', 'concluidas']

const estadoEhValido = (estado: string): boolean => ESTADOS_VALIDOS.includes(estado)

const normalizarTermo = (termo: string | undefined): string =>
  (termo ?? '').trim().toLowerCase()

const combinaEstado = (tarefa: Tarefa, estado: string): boolean => {
  if (estado === 'abertas') {
    return tarefa.concluida === false
  }
  if (estado === 'concluidas') {
    return tarefa.concluida === true
  }
  return true
}

const combinaTermo = (tarefa: Tarefa, termo: string): boolean =>
  termo === '' || tarefa.titulo.toLowerCase().includes(termo)

export function filtrarTarefas(tarefas: Tarefa[], filtro: { estado: string, termo?: string }): Tarefa[] {
  const { estado, termo } = filtro
  if (!estadoEhValido(estado)) {
    throw new Error('Estado inválido')
  }
  const termoNormalizado = normalizarTermo(termo)
  return tarefas.filter((tarefa) => combinaEstado(tarefa, estado) && combinaTermo(tarefa, termoNormalizado))
}
